import {readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';
const root=process.cwd(),seen=new Set(),{snackDomSourceContext}=await import(pathToFileURL(join(root,'scripts/snack-dom-source-context.mjs')));
const read=p=>{seen.add(p);return readFileSync(join(root,p));};
const q=snackDomSourceContext({root,read});
if(q.raw!==read)throw new Error('raw current owner changed');
const report={line:q.line,raw_current_owner_passed:true,read_paths:[...seen].sort(),historical_subject_used_as_current:false};
writeFileSync(process.argv[2],JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({line:q.line,raw_current_owner_passed:true,observed_reads:seen.size}));
